/* Teaching presentation uses the trainer's actual interpreter and material model. */
(()=>{'use strict';
 const T=window.Trainer;if(!T)return;
 const root=document.createElement('section');root.id='studio';
 root.innerHTML=`<header class="studio-header"><div class="studio-brand"><img src="../../brand/is4s-badge.svg" alt="ACCESS Indigenous Skills4Success"><span>CNC workshop</span></div><div class="studio-series">MACHINIST · CNC PROJECTS</div><div class="studio-number"></div></header><div class="studio-op"></div><aside class="studio-board"><div class="studio-kicker">PROJECT &amp; ACTIVE PROGRAM</div><h1 class="studio-title"></h1><div class="studio-material"></div><div class="studio-blocks"></div><div class="studio-data"><div><span>SPINDLE · RPM</span><strong id="studio-rpm">0</strong></div><div><span>FEED · MM/MIN</span><strong id="studio-feed">0</strong></div><div><span>ACTIVE TOOL</span><strong id="studio-tool">—</strong></div></div><p class="studio-math"></p></aside><div class="studio-view-label">SIMULATION · ENCLOSURE HIDDEN FOR VISIBILITY</div><div class="studio-controls"><button data-action="start">Cycle start</button><button data-action="hold">Feed hold</button><button data-action="reset">Reset</button><button data-view="part">Part</button><button data-view="top">Top</button><button data-view="front">Front</button><button data-view="iso">Machine</button></div><div class="studio-caption"></div><div class="studio-progress"><div></div></div><button class="studio-exit">Full controls</button>`;
 document.body.append(root);
 const q=s=>root.querySelector(s),esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
 let project=null,operation=null,recording=false;
 function draw(){
  const S=T.S,st=S.curStep||(S.steps[S.i]||null),main=T.currentProg(),source=st&&main&&st.prog!==main.o?T.LIB.find(p=>p.o===st.prog):null,lines=(source?source.text:S.text).split('\n'),line=st?st.line:0;
  let first=Math.max(0,line-2);if(first+6>lines.length)first=Math.max(0,lines.length-6);
  q('.studio-kicker').textContent=S.curStep?'PROJECT & ACTIVE PROGRAM':'PROJECT · READY TO RUN';
  q('.studio-blocks').innerHTML=lines.slice(first,first+6).map((v,i)=>{const clean=v.replace(/\([^)]*\)/g,'').trim()||v;return `<div class="${first+i===line&&S.curStep?'active':'code-line'}">${esc(clean||' ')}</div>`;}).join('');
  q('#studio-rpm').textContent=Math.round(S.rpm).toLocaleString('en');q('#studio-tool').textContent=S.tool?'T'+S.tool:'—';
  q('#studio-feed').textContent=st&&st.k==='move'?(st.kind==='rapid'?'RAPID':(st.ipm*25.4).toFixed(0)):'—';
  if(!recording){q('.studio-progress div').style.width=(S.total?100*S.simTime/S.total:0)+'%';if(S.alarm)q('.studio-caption').textContent=S.alarm;}
  return T.trainingSnapshot();
 }
 function setOperation(op){operation=op||{};q('.studio-op').textContent=operation.title||'Setup and workholding';q('.studio-math').textContent=(operation.math||[]).join('\n');if(operation.view)T.trainingView(operation.view);}
 function begin(p,{manual=false}={}){
  project=p;recording=manual;
  if(p)T.loadTrainingProject(p);
  else project={id:'PRACTICE',title:T.currentProg().title,material:{name:'User-selected setup'}};
  document.body.classList.add('teaching-view');document.body.classList.toggle('recording',manual);
  document.documentElement.style.setProperty('--studio-scale',Math.min(1,innerWidth/1280));
  T.manualPlayback(manual);T.trainingView('part');
  q('.studio-title').textContent=project.title;q('.studio-number').textContent=project.id;
  q('.studio-material').textContent=project.material.name;
  q('.studio-caption').textContent=manual?'':'Cycle start runs the actual program. Feed hold pauses the operation.';
  setOperation(project.operations&&project.operations[0]);window.dispatchEvent(new Event('resize'));return draw();
 }
 const videoBrand=new Image();videoBrand.src='data:image/svg+xml;base64,';
 const videoCanvas=document.createElement('canvas');videoCanvas.width=1280;videoCanvas.height=720;
 function videoFrame(){
  if(!recording)throw Error('Recording mode required');
  const c=videoCanvas.getContext('2d');
  const rect=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(x,y,w,h);};
  const text=(v,x,y,size,col='#1A1A1A',weight=500,font='Segoe UI')=>{c.font=`${weight} ${size}px ${font}`;c.fillStyle=col;c.fillText(String(v),x,y);};
  function wrap(v,x,y,maxWidth,size,lineHeight,col,weight=500,maxLines=10){
   c.font=`${weight} ${size}px Segoe UI`;const words=String(v).split(/\s+/);let lines=[],line='';
   for(const word of words){const next=line?line+' '+word:word;if(c.measureText(next).width>maxWidth&&line){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);
   if(lines.length>maxLines)throw Error('Presentation text exceeds measured area: '+v);
   lines.forEach((s,i)=>text(s,x,y+i*lineHeight,size,col,weight));return lines.length;
  }
  rect(0,0,1280,720,'#24272b');
  c.drawImage(document.querySelector('#viewport canvas'),0,64,840,556);
  rect(840,64,440,556,'#F4F5F6');rect(840,64,2,556,'#E5E7E9');
  if(videoBrand.complete&&videoBrand.naturalWidth)c.drawImage(videoBrand,24,3,64,59);text('CNC workshop',104,39,21,'#ffffff',750);text('MACHINIST · CNC PROJECTS',293,39,14,'#ffffff',500);text(project.id,1135,40,19,'#FFEBB2',700);
  const op=operation||{};c.font='650 21px Segoe UI';const opWidth=Math.min(794,c.measureText(op.title||'Setup and workholding').width+32);rect(22,81,opWidth,43,'rgba(36,39,43,.93)');wrap(op.title||'Setup and workholding',41,109,755,21,25,'#ffffff',650,1);
  text(T.S.curStep?'PROJECT & ACTIVE PROGRAM':'PROJECT · READY TO RUN',866,95,12,'#9E1217',700);
  wrap(project.title,866,128,390,25,29,'#1A1A1A',750,2);text(project.material.name,866,191,14,'#4A4E54',500);
  rect(866,207,390,183,'#1A1A1A');
  const code=[...q('.studio-blocks').children];code.forEach((line,i)=>{if(line.classList.contains('active'))rect(870,216+i*26,386,26,'#FFBC00');let size=16,value=line.textContent;const weight=line.classList.contains('active')?800:500;c.font=`${weight} ${size}px Consolas`;while(c.measureText(value).width>368&&size>11){size--;c.font=`${weight} ${size}px Consolas`;}if(c.measureText(value).width>368){while(value.length&&c.measureText(value+'…').width>368)value=value.slice(0,-1);value+='…';}c.save();c.beginPath();c.rect(879,216+i*26,368,26);c.clip();text(value,879,235+i*26,size,line.classList.contains('active')?'#1A1A1A':'#F4F5F6',weight,'Consolas');c.restore();});
  [['SPINDLE · RPM','#studio-rpm'],['FEED · MM/MIN','#studio-feed'],['ACTIVE TOOL','#studio-tool']].forEach((v,i)=>{text(v[0],866+i*130,421,11,'#4A4E54');text(q(v[1]).textContent,866+i*130,447,19,'#1A1A1A',750);});rect(866,460,390,1,'#E5E7E9');
  let my=490;for(const line of op.math||[]){my+=wrap(line,866,my,390,17,24,'#9E1217',600,2)*24;if(my>606)throw Error('Math exceeds presentation board');}
  rect(24,583,370,27,'rgba(36,39,43,.9)');text('SIMULATION · ENCLOSURE HIDDEN FOR VISIBILITY',33,601,12,'#F4F5F6');
  rect(0,620,1280,97,'#24272b');const cap=q('.studio-caption').textContent;
  c.font='500 27px Segoe UI';const words=cap.split(/\s+/),cl=[];let line='';for(const word of words){const next=line?line+' '+word:word;if(c.measureText(next).width>1080&&line){cl.push(line);line=word;}else line=next;}if(line)cl.push(line);if(cl.length>2)throw Error('Caption exceeds two lines');
  cl.forEach((v,i)=>{c.font='500 27px Segoe UI';text(v,(1280-c.measureText(v).width)/2,(cl.length===1?678:660)+i*36,27,'#ffffff');});
  rect(0,717,1280,3,'#8E9298');rect(0,717,1280*parseFloat(q('.studio-progress div').style.width||'0')/100,3,'#FFBC00');
  return videoCanvas.toDataURL('image/jpeg',.9);
 }
 window.CNCStudio={begin,setOperation,draw,videoFrame,frame({advance=0,wallDt=0,caption='',progress=0}){if(!recording)throw Error('Recording mode required');const state=T.advanceTraining(advance,wallDt);q('.studio-caption').textContent=caption;q('.studio-progress div').style.width=Math.max(0,Math.min(100,progress*100))+'%';draw();return state;},end(){T.manualPlayback(false);recording=false;document.body.classList.remove('teaching-view','recording');window.dispatchEvent(new Event('resize'));}};
 q('.studio-exit').onclick=()=>CNCStudio.end();
 root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>document.getElementById('btn-'+b.dataset.action).click());
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>T.trainingView(b.dataset.view));
 const button=document.createElement('button');button.type='button';button.className='iconbtn studio-toggle';button.textContent='Teaching view';button.onclick=()=>begin(null);document.querySelector('.topbar').append(button);
 if(Array.isArray(window.CNC_PROJECTS)&&CNC_PROJECTS.length){
  const select=document.createElement('select');select.id='training-projects';select.setAttribute('aria-label','Machinist projects');
  select.innerHTML='<option value="">40 project demonstrations</option>'+CNC_PROJECTS.map(p=>`<option value="${esc(p.id)}">${esc(p.id+' · '+p.title)}</option>`).join('');
  select.onchange=()=>{const p=CNC_PROJECTS.find(p=>p.id===select.value);if(p)begin(p);};document.querySelector('.topbar').append(select);
 }
 setInterval(()=>{if(document.body.classList.contains('teaching-view')&&!recording)draw();},100);
})();
